g.style:
stroke: none;
            stroke-width: 0;
            stroke-dasharray: none;
            stroke-linecap: butt;
            stroke-linejoin: miter;
            stroke-miterlimit: 10;
            fill: none;
            fill-rule: nonzero;
            opacity: 1;

path.style:
stroke: currentColor;
             stroke-width: 12;
             stroke-dasharray: none;
             stroke-linecap: round;
             stroke-linejoin: round;
             fill: none;
             fill-rule: nonzero;
             opacity: 1;

circle.style:
stroke: currentColor;
                   stroke-width: 10;
                   stroke-dasharray: none;
                   stroke-linecap: round;
                   stroke-linejoin: round;
                   fill: none;
                   fill-rule: nonzero;
                   opacity: 1;
